def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    reqs = [WATER_REQ]
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            reqs.append(float(opp.get('water_requirement', WATER_REQ)))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    total_req = sum(reqs)
    pressure = total_req / max(supply, 1.0)

    if not alive:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.6
        return max(0.0, min(budget, round(base, 2)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    median_prev = sorted(prev_bids)[int(len(prev_bids) / 2)] if prev_bids else 0.0

    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if pressure <= 2.2:
        base = DAILY_SALARY * 0.42
    elif pressure <= 2.8:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.9

    if highest_prev >= 160:
        if urgent:
            target = max(base, 148.0)
        else:
            target = min(base, DAILY_SALARY * 0.5)
    elif highest_prev >= 120:
        if pressure <= 2.4 and not urgent:
            target = max(base, median_prev + 2.0)
        else:
            target = max(base, highest_prev + 1.5)
    elif highest_prev > 0:
        target = max(base, highest_prev + 2.0)
    else:
        target = base

    rich_threats = 0
    weak_threats = 0
    for oid, opp in alive:
        ob = float(opp.get('budget', 0.0))
        ohp = float(opp.get('hp', 0.0))
        onw = int(opp.get('no_water_days', 0))
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if ob >= 300 and ohp >= 4:
            rich_threats += 1
        if onw >= 1 or ohp <= 2:
            weak_threats += 1
        if pbid is not None and float(pbid) >= 150:
            rich_threats += 1

    if rich_threats >= 2 and not urgent and pressure > 2.5:
        target *= 0.82
    if weak_threats >= 2 and pressure <= 2.4:
        target *= 0.9

    if urgent:
        target = max(target, DAILY_SALARY * 0.95)
    if critical:
        target = max(target, 135.0)

    if day >= 8 and hp >= 6 and budget < 180:
        target *= 0.9
    if day >= 8 and urgent:
        target *= 1.08

    target = min(target, budget)
    target = max(0.0, target)
    return round(target, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids to infer aggressiveness
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: with 15-25 water and requirement 9, typically 1 unit is ~enough for survival.
    # If supply is low, competition is higher.
    supply_factor = 0.0
    if supply <= (MIN_SUPPLY + 1e-6):
        supply_factor = 1.0
    elif supply >= (MAX_SUPPLY - 1e-6):
        supply_factor = 0.2
    else:
        # linear between 15..25
        supply_factor = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)

    # Base bid target: midrange, scaled by supply pressure and our urgency.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.6
    else:
        urgency = 0.2

    # If someone was extremely aggressive yesterday, slightly shadow to avoid losing the key allocation.
    # Use a conservative multiplier to avoid overpaying.
    shadow = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.6:
        shadow = 0.35
    elif highest_prev_bid >= DAILY_SALARY * 1.1:
        shadow = 0.2
    else:
        shadow = 0.05

    # Compute desired bid
    # Healthy hp -> don't overpay; low hp -> pay more.
    hp_factor = 0.0
    if hp <= 1:
        hp_factor = 1.0
    elif hp <= 3:
        hp_factor = 0.75
    elif hp <= 6:
        hp_factor = 0.45
    else:
        hp_factor = 0.25

    # Target around 0.6 salary when supply is low, lower when supply is high.
    target = DAILY_SALARY * (0.45 + 0.35 * supply_factor) * (0.55 + 0.45 * hp_factor)
    target *= (0.75 + 0.5 * urgency)
    target *= (1.0 + shadow)

    # Cap target by a fraction of budget to reduce risk.
    # If budget is already low, bid near budget to maximize survival probability.
    if budget <= DAILY_SALARY * 0.6:
        max_afford = budget
    else:
        max_afford = min(budget, DAILY_SALARY * 0.95)

    bid = min(max_afford, target)

    # Ensure non-negative and at least a minimal competitive amount when we must survive.
    if bid < 0.0:
        bid = 0.0

    # If we are at risk (hp low or no_water_days high), ensure we bid enough to compete.
    if (hp <= 3 or no_water_days >= 2) and bid < DAILY_SALARY * 0.65:
        bid = min(max_afford, DAILY_SALARY * 0.75)

    # If supply is abundant and we are healthy, avoid wasting money.
    if supply >= (MAX_SUPPLY - 1e-6) and hp >= 7 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.4)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']

    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive'] and opp.get('previous_trace') and 'bid' in opp['previous_trace']:
            yesterday_bids.append(opp['previous_trace']['bid'])

    if not yesterday_bids:
        base_bid = DAILY_SALARY * 0.6
    else:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        if hp <= 3 or no_water_days >= 2:
            base_bid = max(DAILY_SALARY * 0.8, avg_bid + 5)
        else:
            base_bid = min(DAILY_SALARY * 0.7, max(DAILY_SALARY * 0.3, avg_bid + 2))

    if supply < 16:
        base_bid *= 1.2

    bid = min(budget, base_bid)
    return round(bid, 2)
